function_enum_variance.source:
enum Handler<T> { Handle(Fun<(T), Unit>) }
fun send(h: Handler<List<Int>>): Unit { match h { Handle(f) => f([1]) } }
let h: Handler<List<NoValue>> = Handle(fun(xs: List<NoValue>): Unit { assert(xs.is_empty()) })
send(h)

function_field_variance.source:
struct Handler<T> { run: Fun<(T), Unit> }
fun send(h: Handler<List<Int>>): Unit { (h.run)([1]) }
let h: Handler<List<NoValue>> = Handler{ run: fun(xs: List<NoValue>): Unit { assert(xs.is_empty()) } }
send(h)

